size_t nbits = binfo->nbits;
    if (min_bit >= nbits) {
        return nbits;
    }

    size_t group_idx = min_bit / binfo->bits_per_group;
    size_t bit_in_group = min_bit % binfo->bits_per_group;
    const size_t *bitmap_groups = bitmap->groups;

    while (group_idx < binfo->ngroups) {
        size_t group = bitmap_groups[group_idx];
        if (group != std::numeric_limits<size_t>::max()) {
            size_t bit = group_idx * binfo->bits_per_group + bit_in_group;
            while (bit_in_group < binfo->bits_per_group) {
                if ((group & (static_cast<size_t>(1) << bit_in_group)) == 0) {
                    return bit;
                }
                bit_in_group++;
                bit++;
            }
        }
        group_idx++;
        bit_in_group = 0;
    }

    return nbits;
    // END_CODE

